import{_ as t,c as l,o,a3 as a,a9 as n,aa as r,ab as c}from"./chunks/framework.MI-M1z4O.js";const f=JSON.parse('{"title":"IntelliJ IDEA 기반 Electron 메인 프로세스 원격 디버거 연결 가이드","description":"IntelliJ IDEA에서 Electron 데스크톱 애플리케이션(SyncETA)의 메인 프로세스 V8 Inspector(ws://127.0.0.1:5858)에 원격 디버거를 연결하고 브레이크포인트를 추적하는 기술 가이드입니다.","frontmatter":{"title":"IntelliJ IDEA 기반 Electron 메인 프로세스 원격 디버거 연결 가이드","description":"IntelliJ IDEA에서 Electron 데스크톱 애플리케이션(SyncETA)의 메인 프로세스 V8 Inspector(ws://127.0.0.1:5858)에 원격 디버거를 연결하고 브레이크포인트를 추적하는 기술 가이드입니다.","head":[["meta",{"name":"keywords","content":"SyncETA, Electron, IntelliJ IDEA, V8 Inspector, 원격 디버깅, 메인 프로세스, Breakpoint"}],["meta",{"property":"og:title","content":"IntelliJ IDEA 기반 Electron 메인 프로세스 원격 디버거 연결 가이드 | Empasy Docs"}],["meta",{"property":"og:description","content":"Electron 메인 프로세스 dev:debug 실행 및 IntelliJ V8 Inspector 소켓 연결, 중단점(Breakpoint) 디버깅 절차 안내입니다."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/logs/20250827_electronDebug"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/logs/20250827_electronDebug"}]],"sort":300},"headers":[],"relativePath":"logs/20250827_electronDebug.md","filePath":"ko/logs/20250827_electronDebug.md","lastUpdated":1795045877000}'),d={name:"logs/20250827_electronDebug.md"};function i(s,e,p,g,h,m){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="intellij-idea-기반-electron-메인-프로세스-원격-디버거-연결-가이드" tabindex="-1">IntelliJ IDEA 기반 Electron 메인 프로세스 원격 디버거 연결 가이드 <a class="header-anchor" href="#intellij-idea-기반-electron-메인-프로세스-원격-디버거-연결-가이드" aria-label="Permalink to “IntelliJ IDEA 기반 Electron 메인 프로세스 원격 디버거 연결 가이드”">​</a></h1><p>SyncETA 데스크톱 애플리케이션은 <strong>Electron 메인 프로세스(Node.js / Playwright 제어)</strong>와 <strong>렌더러 프로세스(Vue 3 UI)</strong>의 멀티 프로세스 구조로 동작합니다. 본 문서는 IntelliJ IDEA에서 V8 Inspector 웹소켓(<code>ws://127.0.0.1:5858</code>)을 통해 Electron 메인 프로세스에 원격 디버거를 연결하고 중단점(Breakpoint)을 추적하는 표준 절차를 설명합니다.</p><hr><h2 id="_1-디버그-모드-dev-debug-실행" tabindex="-1">1. 디버그 모드(<code>dev:debug</code>) 실행 <a class="header-anchor" href="#_1-디버그-모드-dev-debug-실행" aria-label="Permalink to “1. 디버그 모드(dev:debug) 실행”">​</a></h2><p><code>package.json</code>에 정의된 <code>dev:debug</code> 스크립트를 실행하여 Electron 메인 프로세스를 <code>--inspect=5858</code> 플래그와 함께 기동합니다.</p><p><img src="'+n+'" alt="디버그 모드 실행" loading="lazy"></p><table tabindex="0"><thead><tr><th style="text-align:left;">실행 스크립트</th><th style="text-align:left;">내부 플래그</th><th style="text-align:left;">기본 디버그 포트</th></tr></thead><tbody><tr><td style="text-align:left;"><code>yarn dev:debug</code></td><td style="text-align:left;"><code>electron --inspect=5858 .</code></td><td style="text-align:left;"><code>127.0.0.1:5858</code> (V8 Inspector WebSocket)</td></tr></tbody></table><hr><h2 id="_2-v8-inspector-원격-디버거-소켓-연결" tabindex="-1">2. V8 Inspector 원격 디버거 소켓 연결 <a class="header-anchor" href="#_2-v8-inspector-원격-디버거-소켓-연결" aria-label="Permalink to “2. V8 Inspector 원격 디버거 소켓 연결”">​</a></h2><p>터미널 콘솔에 출력되는 <code>Debugger listening on ws://127.0.0.1:5858/...</code> 링크를 <code>Ctrl + Click</code> (또는 <code>Cmd + Click</code>)하여 IntelliJ 내장 JavaScript/Node.js 디버거를 즉시 부착(Attach)합니다.</p><p><img src="'+r+'" alt="디버거 열기" loading="lazy"></p><hr><h2 id="_3-중단점-breakpoint-설정-및-런타임-상태-검사" tabindex="-1">3. 중단점(Breakpoint) 설정 및 런타임 상태 검사 <a class="header-anchor" href="#_3-중단점-breakpoint-설정-및-런타임-상태-검사" aria-label="Permalink to “3. 중단점(Breakpoint) 설정 및 런타임 상태 검사”">​</a></h2><p>메인 프로세스 TypeScript 소스코드(IPC 핸들러, Playwright 브라우저 컨텍스트 제어부 등)에 중단점을 설정하면, 이벤트 호출 시점에 실행이 일시 정지되며 호출 스택(Call Stack)과 로컬 변수 상태를 실시간으로 검사할 수 있습니다.</p><p><img src="'+c+'" alt="Breakpoint" loading="lazy"></p><hr><h2 id="_4-프로세스별-디버깅-타깃-및-주의사항" tabindex="-1">4. 프로세스별 디버깅 타깃 및 주의사항 <a class="header-anchor" href="#_4-프로세스별-디버깅-타깃-및-주의사항" aria-label="Permalink to “4. 프로세스별 디버깅 타깃 및 주의사항”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">프로세스 구분</th><th style="text-align:left;">실행 런타임</th><th style="text-align:left;">디버거 연결 방식</th><th style="text-align:left;">주요 디버깅 대상</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Main Process</strong></td><td style="text-align:left;">Node.js / Electron Main</td><td style="text-align:left;"><code>ws://127.0.0.1:5858</code> V8 Inspector 소켓 연결</td><td style="text-align:left;"><code>ipcMain.handle</code>, Playwright 브라우저 풀 제어, 로컬 파일 I/O</td></tr><tr><td style="text-align:left;"><strong>Preload Script</strong></td><td style="text-align:left;">Isolated Context Bridge</td><td style="text-align:left;">Chromium DevTools (<code>Ctrl+Shift+I</code>) Sources 탭</td><td style="text-align:left;"><code>contextBridge.exposeInMainWorld</code> API 바인딩 검증</td></tr><tr><td style="text-align:left;"><strong>Renderer Process</strong></td><td style="text-align:left;">Chromium / Vue 3</td><td style="text-align:left;">Chromium DevTools 또는 Vite HMR 콘솔</td><td style="text-align:left;">Vue 3 컴포넌트 상태(Pinia), 시나리오 캔버스 UI 렌더링</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>메인 프로세스 중단점에서 장시간 대기할 경우 렌더러 프로세스의 IPC 응답 타임아웃이 발생할 수 있으므로, 비동기 IPC 호출 디버깅 시에는 타임아웃 임계치를 일시 완화하거나 조건부 중단점(Conditional Breakpoint)을 사용하는 것을 권장합니다.</p></div>',19)])])}const _=t(d,[["render",i]]);export{f as __pageData,_ as default};
